// Defensive defaults so every caller gets the same row shape.
const i = $input.first().json;
const ids = Array.isArray(i.matched_faq_ids) ? i.matched_faq_ids.map(Number).filter(Number.isInteger) : [];

return [{ json: {
  session_id: String(i.session_id ?? ''),
  user_message: String(i.user_message ?? ''),
  reply: String(i.reply ?? ''),
  matched_faq_ids: '{' + ids.join(',') + '}', // Postgres int[] literal
  confidence: Math.max(0, Math.min(1, Number(i.confidence) || 0)),
  handoff: i.handoff === true,
} }];

